import unittest

from solucao import frases


class TestPercorrerUmDicionario(unittest.TestCase):
    def test_monta_uma_frase_por_par(self):
        """frases monta uma frase por par chave valor"""
        self.assertEqual(sorted(frases({"a": 1, "b": 2})), ["a=1", "b=2"])

    def test_funciona_com_outro_dicionario(self):
        """frases funciona com outro dicionario"""
        self.assertEqual(sorted(frases({"x": 9})), ["x=9"])

    def test_dicionario_vazio_da_lista_vazia(self):
        """frases de um dicionario vazio devolve a lista vazia"""
        self.assertEqual(sorted(frases({})), [])

